package gemini

import (
	"os"
	"sort"
	"testing"

	"github.com/QuantumNous/new-api/common"
	"github.com/QuantumNous/new-api/dto"
	"github.com/QuantumNous/new-api/setting/model_setting"
	"github.com/QuantumNous/new-api/types"
	"github.com/stretchr/testify/require"
	"github.com/tidwall/gjson"
)

// Expected semantic projections were generated by executing the unmodified
// upstream 718a4e7f97 relaykit.ConvertRequest, not by this local converter.
// Random IDs, host safety defaults and schema wire dialect are not compared;
// message/tool meaning, tool selection, policy outcome and loss codes are.
func TestResponsesUpstreamReferenceFixtures(t *testing.T) {
	input, err := os.ReadFile("testdata/responses_upstream_cases.json")
	require.NoError(t, err)
	expected, err := os.ReadFile("testdata/responses_upstream_expected.json")
	require.NoError(t, err)
	var cases []struct {
		Name    string
		Policy  types.ConversionLossPolicy
		Request dto.OpenAIResponsesRequest
	}
	require.NoError(t, common.Unmarshal(input, &cases))
	want := gjson.ParseBytes(expected).Array()
	require.Len(t, want, len(cases))
	settings := model_setting.GetGeminiSettings()
	old := settings.FunctionCallThoughtSignatureEnabled
	settings.FunctionCallThoughtSignatureEnabled = true
	t.Cleanup(func() { settings.FunctionCallThoughtSignatureEnabled = old })
	for i, test := range cases {
		t.Run(test.Name, func(t *testing.T) {
			c, _, info := responsesTestContext()
			info.ChannelOtherSettings.ToolLossPolicy = test.Policy
			converted, err := ConvertResponsesToGemini(c, info, test.Request)
			actual := map[string]any{"name": test.Name, "rejected": err != nil}
			codes := map[string]bool{}
			for _, d := range info.ConversionDiagnostics() {
				codes[d.Code] = true
			}
			sortedCodes := []string{}
			for code := range codes {
				sortedCodes = append(sortedCodes, code)
			}
			sort.Strings(sortedCodes)
			actual["diagnostic_codes"] = sortedCodes
			if err == nil {
				body, encodeErr := common.Marshal(converted)
				require.NoError(t, encodeErr)
				actual["contents"] = gjson.GetBytes(body, "contents").Value()
				actual["tool_config"] = gjson.GetBytes(body, "toolConfig").Value()
				functions, hosted := []string{}, []string{}
				for _, tool := range gjson.GetBytes(body, "tools").Array() {
					tool.ForEach(func(key, value gjson.Result) bool {
						if key.String() == "functionDeclarations" {
							for _, fn := range value.Array() {
								functions = append(functions, fn.Get("name").String())
							}
						} else {
							hosted = append(hosted, key.String())
						}
						return true
					})
				}
				sort.Strings(functions)
				sort.Strings(hosted)
				actual["function_names"] = functions
				actual["hosted_tools"] = hosted
			}
			raw, encodeErr := common.Marshal(actual)
			require.NoError(t, encodeErr)
			require.JSONEq(t, want[i].Raw, string(raw), "upstream semantic mismatch: %v", err)
		})
	}
}
